import {
  LOCKUP_TOP,
  MARK_CREST,
  MARK_DATUM,
  MARK_DATUM_Y,
  MARK_SCALE,
  MARK_TROUGH,
  MARK_X,
  SWELL_PATH,
  SWELL_RIGHT,
  SWELL_X,
} from "@/components/logoGeometry";

/*
 * The Datum Crest logo, picked by Taryn on 16 October 2026: a grey Datum line,
 * a sine crest rising above it in sand and a shallower trough below it in sea.
 * The Datum line is the baseline of "Swell", which is drawn as outlines
 * (Fraunces 600) because the site only loads Fraunces italic. Geometry is
 * generated by scripts/brand/build_logo.py.
 *
 * The svg's bottom edge is the baseline, so in a baseline-aligned row it lines
 * up with "ANALYTICS"; the trough hangs below it like a descender.
 */
const SWELL_SIZE_PX = 26;
const PX_PER_UNIT = SWELL_SIZE_PX / 2000;

export default function SwellLogo({ id = "logo", className = "" }: { id?: string; className?: string }) {
  const width = SWELL_RIGHT * PX_PER_UNIT;
  const height = -LOCKUP_TOP * PX_PER_UNIT;
  return (
    <span className={`inline-flex items-baseline gap-2 leading-none ${className}`}>
      <svg
        width={width}
        height={height}
        viewBox={`0 ${LOCKUP_TOP} ${SWELL_RIGHT} ${-LOCKUP_TOP}`}
        overflow="visible"
        aria-hidden
      >
        <defs>
          <clipPath id={`${id}-above`}>
            <rect width="64" height={MARK_DATUM_Y} />
          </clipPath>
          <clipPath id={`${id}-below`}>
            <rect y={MARK_DATUM_Y} width="64" height={64 - MARK_DATUM_Y} />
          </clipPath>
        </defs>
        <g transform={`translate(${MARK_X} ${-MARK_DATUM_Y * MARK_SCALE}) scale(${MARK_SCALE})`}>
          <path d={MARK_DATUM} stroke="var(--fg-subtle)" strokeWidth="2.2" />
          <path d={MARK_TROUGH} clipPath={`url(#${id}-below)`} stroke="var(--below)" strokeWidth="5.6" fill="none" />
          <path d={MARK_CREST} clipPath={`url(#${id}-above)`} stroke="var(--above)" strokeWidth="5.6" fill="none" />
        </g>
        <path transform={`translate(${SWELL_X} 0)`} fill="currentColor" d={SWELL_PATH} />
      </svg>
      {/* 11px: the signed mobile bar (check 6) sets the floor for rendered text. */}
      <span className="text-[0.6875rem] font-semibold tracking-[0.2em] text-chrome-fg-muted">ANALYTICS</span>
    </span>
  );
}
